"""Generate src/server/KitManifest.luau from the batch manifests + the
Roblox mesh ids of the imported FBX (tools/blender/kit_mesh_ids.json).

  python tools/blender/gen_kit_manifest.py
"""
import json
import os

ROOT = os.path.dirname(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
KIT = os.path.join(ROOT, "assets", "models", "kit")
ids = json.load(open(os.path.join(ROOT, "tools", "blender", "kit_mesh_ids.json"), encoding="utf-8"))


def v3(v):
    return "{%s}" % ", ".join(f"{x:g}" for x in v)


lines = [
    "--!strict",
    "-- GENERATED by tools/blender/gen_kit_manifest.py from assets/models/kit/<batch>/*.json",
    "-- and tools/blender/kit_mesh_ids.json. Do not edit by hand.",
    "--",
    "-- Per mesh: id (Roblox mesh asset), group, c = bbox centre and s = size in",
    "-- the group's local frame (Roblox axes, studs, origin = the group's pivot,",
    "-- front = -Z), tint/glow/glass flags, place = scale-1 world pivots.",
    "return {",
]
missing = []
for batch in ("batch1", "batch2", "batch3", "office", "rooms", "annex", "batch4", "batch5", "lobby", "xmas"):
    data = json.load(open(os.path.join(KIT, batch, f"motel_kit_{batch}.json"), encoding="utf-8"))
    for name, m in data["meshes"].items():
        # Meshes not imported yet get no id: the game uses them only once a
        # template with that name is in ServerStorage.MotelKit.
        fields = [f'group = "{m["group"]}"', f"c = {v3(m['center'])}", f"s = {v3(m['size'])}"]
        if name in ids:
            fields.insert(0, f'id = "{ids[name]}"')
        else:
            missing.append(name)
        if m.get("hinge"):
            fields.append(f"hinge = {v3(m['hinge'])}")
            fields.append(f"swing = {m['swing']:g}")
        for flag in ("tint", "glow", "glass"):
            if m.get(flag):
                fields.append(f"{flag} = true")
        if m.get("place"):
            fields.append("place = {%s}" % ", ".join(v3(p) for p in m["place"]))
        lines.append(f"\t{name} = {{ {', '.join(fields)} }},")
# Meshes from other Blender scripts (not in a kit batch manifest).
# Centres are measured from the import (trunk base = origin), in the
# intended frame (the importer's 180-degree turn undone).
EXTRA = {
    # tools/blender/pine_tree.py -> assets/models/pine_tree/fbx/pine_tree.fbx
    "PineTrunk": {"group": "PineTree", "center": [0, 3.2, 0], "size": [2.804, 6.4, 2.948]},
    "PineLeaves": {"group": "PineTree", "center": [-0.294, 14.023, 0], "size": [14.108, 19.755, 14.253]},
    # tools/blender/pine_tree.py <root> snow -> assets/models/pine_tree_snow/fbx/pine_tree_snow.fbx
    # (same frame as PineTree: offsets from the trunk centre, printed by the script).
    "PineSnowTrunk": {"group": "PineTreeSnow", "center": [0, 3.2, 0], "size": [2.804, 6.4, 2.948]},
    "PineSnowLeaves": {"group": "PineTreeSnow", "center": [-0.294, 14.022, 0], "size": [14.108, 19.755, 14.253]},
    "PineSnowCap": {"group": "PineTreeSnow", "center": [-0.253, 15.448, 0], "size": [11.838, 17.464, 11.925]},
}
for name, m in EXTRA.items():
    fields = [f'group = "{m["group"]}"', f"c = {v3(m['center'])}", f"s = {v3(m['size'])}"]
    if name in ids:
        fields.insert(0, f'id = "{ids[name]}"')
    else:
        missing.append(name)
    lines.append(f"	{name} = {{ {', '.join(fields)} }},")
lines.append("}")
open(os.path.join(ROOT, "src", "server", "KitManifest.luau"), "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
print("meshes:", len(lines) - 9, "missing ids:", missing)
